import { getD1PostBySlug, loadAllPosts, CATEGORY_LABELS } from '../lib/store.js';

function esc(s = '') {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export async function onRequestGet({ params, request, env, next }) {
  // First try static asset generated by build_news_site.mjs
  const staticRes = await next();
  if (staticRes && staticRes.status !== 404) {
    return staticRes;
  }

  const slug = String(params.slug || '').replace(/\/+$/, '');
  if (!slug) return new Response('Not Found', { status: 404 });

  const d1Post = await getD1PostBySlug(slug, env);
  if (!d1Post) {
    return new Response('Story Not Found', { status: 404 });
  }

  const allPosts = await loadAllPosts(request, env);
  const related = allPosts.filter((p) => p.slug !== slug).slice(0, 5);
  const title = d1Post.title;
  const catLabel = d1Post.category_label || d1Post.categoryLabel || CATEGORY_LABELS[d1Post.category] || 'फाइनेंस न्यूज़';
  const image = d1Post.featured_image || d1Post.featuredImage || '/assets/favicon.png';
  const authorName = d1Post.author_name || d1Post.authorName || 'राहुल शर्मा';
  const publishedAt = d1Post.published_at || d1Post.publishedAt || new Date().toISOString();
  const excerpt = d1Post.excerpt || d1Post.subtitle || title;
  const content = d1Post.content || `<p>${esc(excerpt)}</p>`;

  const dateText = new Date(publishedAt).toLocaleString('hi-IN', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    timeZone: 'Asia/Kolkata',
  });

  const html = `<!doctype html>
<html lang="hi">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>${esc(title)} | LoanKaise.in</title>
  <meta name="description" content="${esc(excerpt)}">
  <link rel="canonical" href="https://loankaise.in/news/${esc(slug)}/">
  <link rel="icon" href="/assets/favicon.png" sizes="192x192" type="image/png">
  <link rel="stylesheet" href="/assets/style.css?v=20260726a">
  <link rel="stylesheet" href="/assets/news.css?v=20261111a">
  <meta name="google-adsense-account" content="ca-pub-4298058382758528">
  <script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-4298058382758528" crossorigin="anonymous"></script>
</head>
<body>
  <div class="topline"></div>
  <header class="site-header">
    <nav class="nav">
      <a class="brand" href="/"><span class="logo">₹</span><span>LoanKaise<span style="color:#08775c">.in</span></span></a>
      <button class="menu-btn" aria-label="Menu">☰</button>
      <div class="navlinks">
        <a href="/news/">Finance News</a>
        <a href="/category/loan-blog/">Loan Blog</a>
        <a href="/mock-test/">Mock Test</a>
        <a href="/calculators/">Calculator</a>
        <a href="/#guides">Banking Guides</a>
        <a href="/contact-us/">Contact</a>
      </div>
    </nav>
  </header>

  <div class="article-wrap" style="display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:22px;align-items:start">
    <main class="article">
      <div class="breadcrumbs"><a href="/">Home</a> / <a href="/news/">Finance News</a> / <span>${esc(catLabel)}</span></div>
      <span class="tag" style="margin-top:0;margin-bottom:10px">${esc(catLabel)}</span>
      <h1>${esc(title)}</h1>
      <div class="lk-author-strip">
        <span><strong>${esc(authorName)}</strong><span class="lk-verified">✓</span></span>
        <span>•</span>
        <time datetime="${esc(publishedAt)}">अपडेट: ${esc(dateText)} IST</time>
      </div>
      <img class="lk-article-hero-img" src="${esc(image)}" alt="${esc(title)}" width="1200" height="675">
      <div class="notice"><b>महत्वपूर्ण सूचना:</b> निवेश, लोन या ब्याज दर से जुड़ा कोई भी निर्णय लेने से पहले संबंधित बैंक या RBI/SEBI नियम अवश्य जांच लें।</div>
      <div class="entry-content">${content}</div>
    </main>

    <aside class="sidebar" style="display:block">
      <div class="sidebox" style="margin-bottom:16px">
        <h3>ताज़ा फाइनेंस न्यूज़</h3>
        ${related.map((r) => `<a href="/news/${esc(r.slug)}/">${esc(r.title)}</a>`).join('\n')}
      </div>
      <div class="sidebox">
        <h3>फ्री बैंकिंग टूल्स</h3>
        <a href="/emi-calculator/">EMI Calculator</a>
        <a href="/loan-eligibility/">Loan Eligibility Check</a>
        <a href="/prepayment-calculator/">Prepayment Savings</a>
        <a href="/income-tax-calculator/">Income Tax Calculator</a>
      </div>
    </aside>
  </div>

  <footer class="footer">
    <div class="copyright">© 2026 LoanKaise.in • Educational &amp; Financial News Portal</div>
  </footer>
  <script src="/assets/app.js?v=20260726a"></script>
</body>
</html>`;

  return new Response(html, {
    status: 200,
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  });
}
